function up(e){if(!gesture)return;if(gesture.kind==='draw'&&draft){const good=draft.type==='room'?draft.w>.15&&draft.h>.15:Math.hypot(draft.x2-draft.x,draft.y2-draft.y)>.15;if(good){checkpoint();v().objects.push(copy(draft));selected=[draft.id];}draft=null;}gesture=null;save();draw();inspector();}
