function zoom(ratio,p){fitMode=false;const c=v().camera,anchor=p||{x:c[0]+c[2]/2,y:c[1]+c[3]/2},nw=Math.min(v().base.viewBox[2]*5,Math.max(v().base.viewBox[2]/20,c[2]*ratio)),f=nw/c[2];v().camera=[anchor.x-(anchor.x-c[0])*f,anchor.y-(anchor.y-c[1])*f,nw,c[3]*f];draw();save();}
