function inspector(){const el=root?.querySelector('#st-inspector');if(!el)return;const o=pick(),m=metrics(),cv=coverage(),groups=[...new Set([...Object.keys(colors),...(D.stakeholders||[]).map(s=>s.name)])];let props='';
if(o){const isLine=o.type==='wall'||o.type==='measure';props=`<section><div class="id">ONTWERPVOORSTEL · ${esc(o.type)}</div><h2>${esc(o.name)}</h2><label>Naam<input data-prop="name" value="${esc(o.name)}"></label><div class="propgrid"><label>X (${v().scale?'m':'eenheden'})<input type="number" step="0.1" data-prop="x" value="${+(o.x*(v().scale||1)).toFixed(3)}"></label><label>Y (${v().scale?'m':'eenheden'})<input type="number" step="0.1" data-prop="y" value="${+(o.y*(v().scale||1)).toFixed(3)}"></label>${isLine?`<label>Eind X<input type="number" step=".1" data-prop="x2" value="${+(o.x2*(v().scale||1)).toFixed(3)}"></label><label>Eind Y<input type="number" step=".1" data-prop="y2" value="${+(o.y2*(v().scale||1)).toFixed(3)}"></label>`:`<label>Breedte (${v().scale?'m':'eenheden'})<input type="number" min=".1" step=".1" data-prop="w" value="${+(o.w*(v().scale||1)).toFixed(3)}"></label>${o.h?`<label>Diepte (${v().scale?'m':'eenheden'})<input type="number" min=".1" step=".1" data-prop="h" value="${+(o.h*(v().scale||1)).toFixed(3)}"></label>`:''}`}${o.type!=='room'&&!isLine?`<label>Draaien (graden)<input type="number" step="15" data-prop="rotation" value="${o.rotation||0}"></label>`:''}</div>${o.type==='room'?`<p class="small">Oppervlakte: <strong>${area(unionArea(rects(o)))}</strong>Getekende zone; geen netto gebruiksoppervlak.</p><label>Gebruiker<select data-prop="user">${groups.map(g=>`<option ${o.user===g?'selected':''}>${g}</option>`).join('')}</select></label><label>Ruimtefunctie<select data-prop="function"><option value="">Nog niet toegewezen</option>${Object.values(D.rooms).map(r=>`<option value="${r.id}" ${o.function===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><button class="btn" data-act="splitv">Splits verticaal</button> <button class="btn" data-act="splith">Splits horizontaal</button>`:''}<button class="btn primary" data-act="apply">Eigenschappen toepassen</button><button class="btn" data-act="duplicate">Object dupliceren</button> <button class="btn" data-act="delete">Verwijderen</button>${selected.length>1?`<button class="btn" data-act="merge">${selected.length} ruimtes samenvoegen</button>`:''}${o.type==='door'||o.type==='wall'?'<p class="warn small">Nieuwe ingreep: controle van bestaande constructie, doorgang, vluchtweg en installaties vereist.</p>':''}</section>`;}else props=`<section><h3>Ruimte-informatie</h3><p>Selecteer een getekende ruimte, wand of meubel. De oorspronkelijke onderlegger is vergrendeld en kan niet worden aangepast.</p><p class="srhint">Tekenen kan ook exact via de numerieke eigenschappen na het plaatsen. Meubelmaten zijn bewerkbare startwaarden, geen gemeten inventaris.</p></section>`;
let research='';if(o?.type==='room'&&o.function){const r=D.rooms[o.function],ws=roomWishes(o);research=`<h3>Onderzoek bij deze ruimte</h3><p><strong>${esc(r.name)}</strong> ${esc(r.sharing)}</p><p class="small"><b>Voorzieningen:</b> ${esc(r.facilities)}</p><div class="checklist">${ws.map(w=>`<label><input type="checkbox" data-wishcheck="${w.id}" ${(o.wishes||[]).includes(w.id)?'checked':''}><b>${w.id} · ${esc(w.org)}</b> ${esc(w.title)} <a href="#wensen?id=${w.id}">bron ${w.source} ${esc(w.time)}</a></label>`).join('')}</div><p class="mini">Functietoewijzing suggereert relaties. Vink alleen de punten aan die je ontwerp conceptueel beoogt te ondersteunen. Dit bewijst geen vervulling.</p><p class="small"><b>VIA-T:</b> ${r.advice.length?r.advice.map(id=>`<a href="#viat?advice=${id}">${esc(D.advice[id].title)}</a> (algemene koppeling)`).join('; '):'Niet besproken door VIA-T: geen specifiek advies over deze functie.'}</p><p class="small"><b>Nog onderzoeken:</b> ${esc(r.unknown)}</p>`;}
const rooms=m.rooms,alerts=[];if(!v().scale)alerts.push('Schaal ontbreekt: geen betrouwbare metrische maat of oppervlakte.');if(m.overlap>.01)alerts.push('Getekende ruimtes overlappen; oppervlakten worden in de totaalsom als geometrische unie geteld.');if(m.outside>.01)alerts.push('Een of meer ruimtezones liggen buiten de broncontour.');if(v().objects.some(o=>['wall','door'].includes(o.type)))alerts.push('Nieuwe wand/deur: constructie, vluchtweg, brandveiligheid en installaties menselijk controleren.');if(v().base.builtin)alerts.push('Binnenindeling en deurposities in de bron zijn ingeschat; ook na kalibratie veldcontrole nodig.');
const missing=D.wishes.filter(w=>!cv.includes(w.id));el.innerHTML=(window.ManegeGenerator?.checklist(v())||'')+props+(window.ManegeGenerator?.explanation(o)||'')+`<section class="check">${research}<h3>Onderzoekscheck</h3><p><strong>${rooms.length} getekende ruimtes · ${cv.length} van ${D.wishes.length} uitspraken gemarkeerd</strong>Markeringen zijn ontwerpintenties, geen bewezen vervulling of score.</p><p>Unie ruimtezones: ${area(m.union)}<br>Som per ruimte: ${area(m.sum)}<br>Referentie broncontour: ${m.gross!==null?area(m.gross):'onbekend'}<br>Niet ingekleurd binnen broncontour: ${m.gross!==null?area(Math.max(0,m.gross-m.inside)):'onbekend'}</p><p class="mini">Bruto geometrie, inclusief ongespecificeerde constructies. Geen netto beschikbare oppervlakte, wettelijke toets of capaciteitsnorm. Bron noemt ook 1.184 m²; de maatvoering 42,12 × 28,03 geeft circa 1.180,62 m². Verschil niet stilzwijgend opgelost.</p><details><summary>Controlepunten (${alerts.length})</summary><div><ul>${alerts.map(a=>`<li>${esc(a)}</li>`).join('')||'<li>Geen eenvoudige geometrische signalen. Menselijke en bouwkundige beoordeling blijft nodig.</li>'}</ul></div></details><details><summary>Nog niet gemarkeerde uitspraken (${missing.length})</summary><div class="research-links">${missing.map(w=>`<p><a href="#wensen?id=${w.id}">${w.id} · ${esc(w.title)}</a></p>`).join('')}</div></details><h3>Ontwerpobjecten</h3><div class="objectlist">${v().objects.map(x=>`<button data-select="${x.id}" class="${selected.includes(x.id)?'selected':''}">${esc(x.name)} · ${esc(x.type)}</button>`).join('')||'Nog geen ontwerpobjecten.'}</div></section>`;}
function click(e){const b=e.target.closest('button');if(!b)return;if(b.dataset.tool){tool=b.dataset.tool;calPoints=[];draw();return;}if(b.dataset.select){selected=e.shiftKey?[...new Set([...selected,b.dataset.select])]:[b.dataset.select];draw();inspector();return;}if(b.dataset.act)action(b.dataset.act);}
function change(e){const t=e.target,o=pick();if(t.dataset.prop&&o){checkpoint();const k=t.dataset.prop;if(['name','user','function'].includes(k)){if(k==='function'&&o.function!==t.value)o.functions=[t.value];o[k]=t.value;if(k==='function'||k==='user')o.wishes=(o.wishes||[]).filter(id=>roomWishes(o).some(w=>w.id===id));}else{let n=Number(t.value);if(!Number.isFinite(n)){notice='Voer een geldig getal in.';inspector();status();return;}if(k!=='rotation')n/=v().scale||1;if(['w','h'].includes(k)){if(n<=0){inspector();return;}if(o.parts){const f=n/o[k];o.parts=o.parts.map(p=>k==='w'?{...p,x:p.x*f,w:p.w*f}:{...p,y:p.y*f,h:p.h*f});}}o[k]=n;}commit();return;}if(t.dataset.wishcheck&&o){checkpoint();o.wishes=o.wishes||[];o.wishes=t.checked?[...new Set([...o.wishes,t.dataset.wishcheck])]:o.wishes.filter(x=>x!==t.dataset.wishcheck);commit();return;}
const states={'st-grid':()=>grid=t.checked,'st-snap':()=>snap=t.checked,'st-wallsnap':()=>snapWalls=t.checked,'st-base':()=>showBase=t.checked,'st-proposals':()=>showProposals=t.checked,'st-labels':()=>showLabels=t.checked,'st-dimensions':()=>showDimensions=t.checked,'st-opacity':()=>opacity=Number(t.value),'st-gridstep':()=>{}};if(states[t.id]){states[t.id]();draw();}}
async function action(a){const o=pick();notice='';if(a==='save'){save('Handmatig opgeslagen op deze browser. Bewaar ook JSON voor andere apparaten.');return;}if(a==='undo'||a==='redo'){const from=a==='undo'?undo:redo,to=a==='undo'?redo:undo;if(from.length){to.push(copy(v()));const snap=from.pop(),idx=project.variants.findIndex(x=>x.id===v().id);project.variants[idx]=snap;selected=[];commit('Wijziging '+(a==='undo'?'ongedaan gemaakt':'opnieuw uitgevoerd')+'.');}return;}
if(a==='zoomin'||a==='zoomout'){zoom(a==='zoomin'?.8:1.25);return;}if(a==='fit'||a==='reference'){if(a==='reference'&&!v().scale)return;fitView();return;}if(a==='toggle-tools'||a==='toggle-inspector'){root.querySelector('.three').classList.toggle(a==='toggle-tools'?'hide-tools':'hide-inspector');requestAnimationFrame(()=>fitView());return;}
if(a==='new'){const n=await ask('Naam van de nieuwe, lege variant:','Nieuwe variant');if(n){const nv=fresh(n);nv.base=copy(v().base);nv.scale=v().scale;nv.scaleNote=v().scaleNote;nv.camera=copy(nv.base.viewBox);project.variants.push(nv);project.active=nv.id;selected=[];undo=[];redo=[];save();refresh();}return;}
if(a==='rename'){const n=await ask('Variantnaam:',v().name);if(n){v().name=n;save();refresh();}return;}
if(a==='copyvariant'){const n=await ask('Naam van de kopie:',v().name+' – kopie');if(n){const nv=copy(v());nv.id=uid();nv.name=n;nv.objects.forEach(o=>o.id=uid());project.variants.push(nv);project.active=nv.id;selected=[];undo=[];redo=[];save();refresh();}return;}
if(a==='delvariant'){if(project.variants.length===1){notice='De laatste variant kan niet worden verwijderd. Maak eerst een nieuwe variant.';status();return;}if(await askConfirm('Deze variant verwijderen? Bewaar eerst JSON als je deze later nodig hebt.')){project.variants=project.variants.filter(x=>x.id!==v().id);project.active=project.variants[0].id;selected=[];undo=[];redo=[];save();refresh();}return;}
if(a==='compare'){compare=!compare;comparePanel();return;}
if(a==='source-scale'){if(!v().base.builtin){notice='Voor deze geïmporteerde onderlegger: kalibreer twee punten met een bekende maat.';status();return;}if(await askConfirm('42,12 m is de breedte volgens de aangeleverde vectorbron. Deze maat is hier niet onafhankelijk geverifieerd. Deze bronmaat gebruiken voor indicatieve metrische berekeningen?')){checkpoint();v().scale=1;v().scaleNote='Bronmaat door gebruiker bevestigd (indicatief)';commit('Bronmaat geactiveerd; binnenindeling blijft geschat.');}return;}
if(a==='clearscale'){checkpoint();v().scale=null;v().scaleNote='Niet bevestigd';commit('Schaal gewist; metrische waarden verborgen.');return;}
if(a==='furniture'){tool='furniture:'+root.querySelector('#st-furniture').value;draw();return;}
if(a==='import'){root.querySelector('#st-import').click();return;}if(a==='open'){root.querySelector('#st-open').click();return;}if(a==='json'){download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),'Manege-ontwerpen.json');return;}if(a==='png'||a==='pdf'){exportDesign(a).catch(err=>{notice='Export mislukt: '+err.message;status();});return;}
if(!o){notice='Selecteer eerst een ontwerpobject.';status();return;}
if(a==='apply'){checkpoint();for(const input of root.querySelectorAll('[data-prop]')){const k=input.dataset.prop;if(['name','user','function'].includes(k)){if(k==='function'&&o.function!==input.value)o.functions=[input.value];o[k]=input.value;}else{let n=Number(input.value);if(!Number.isFinite(n))continue;if(k!=='rotation')n/=v().scale||1;if(['w','h'].includes(k)){if(n<=0)continue;if(o.parts){const f=n/o[k];o.parts=o.parts.map(p=>k==='w'?{...p,x:p.x*f,w:p.w*f}:{...p,y:p.y*f,h:p.h*f});}}o[k]=n;}}commit('Eigenschappen toegepast.');return;}if(a==='delete'){checkpoint();v().objects=v().objects.filter(x=>!selected.includes(x.id));selected=[];commit();return;}
if(a==='duplicate'){checkpoint();const dup=selected.map(id=>copy(obj(id))).filter(Boolean),offset=cell();dup.forEach(n=>{n.id=uid();n.name+=' – kopie';n.x+=offset;n.y+=offset;if('x2'in n){n.x2+=offset;n.y2+=offset;}});v().objects.push(...dup);selected=dup.map(x=>x.id);commit();return;}
if(a==='merge'){const rooms=selected.map(obj).filter(Boolean);if(rooms.some(x=>x.type!=='room')||rooms.length<2){notice='Selecteer meerdere ruimtes met Shift+klik. Andere objecttypen kunnen niet worden samengevoegd.';status();return;}checkpoint();const rs=rooms.flatMap(rects),x=Math.min(...rs.map(r=>r.x)),y=Math.min(...rs.map(r=>r.y)),right=Math.max(...rs.map(r=>r.x+r.w)),bottom=Math.max(...rs.map(r=>r.y+r.h));const n={...copy(rooms[0]),id:uid(),name:'Samengevoegde ruimte',x,y,w:right-x,h:bottom-y,parts:rs.map(r=>({...r,x:r.x-x,y:r.y-y})),wishes:[...new Set(rooms.flatMap(r=>r.wishes||[]))]};v().objects=v().objects.filter(x=>!selected.includes(x.id));v().objects.push(n);selected=[n.id];commit('Zones samengevoegd met behoud van hun geometrie. Interne wanden en doorgangen worden niet automatisch verwijderd. Controleer functie en markeringen.');return;}
if(a==='splitv'||a==='splith'){if(o.type!=='room'||o.parts){notice='Splitsen werkt op één rechthoekige ruimte. Bij samengestelde zones: teken nieuwe deelzones; geometrie wordt niet verzonnen.';status();return;}const fraction=Number(await ask('Splitspercentage vanaf links (verticaal) of boven (horizontaal):','50'))/100;if(!Number.isFinite(fraction)||fraction<=0||fraction>=1)return;checkpoint();const first=copy(o),second=copy(o);first.id=uid();second.id=uid();first.name+=' A';second.name+=' B';if(a==='splitv'){first.w=o.w*fraction;second.x=o.x+first.w;second.w=o.w-first.w;}else{first.h=o.h*fraction;second.y=o.y+first.h;second.h=o.h-first.h;}v().objects=v().objects.filter(x=>x.id!==o.id);v().objects.push(first,second);selected=[first.id];commit('Ruimtezone gesplitst. Teken een scheidingswand apart indien gewenst; onderzoeksmarkeringen opnieuw beoordelen.');}}
function comparePanel(){const el=root?.querySelector('#st-compare');if(!el)return;if(!compare){el.innerHTML='';return;}el.innerHTML=`<section class="comparepanel"><h3>Varianten vergelijken</h3><div class="tablewrap"><table class="matrix"><thead><tr><th>Variant</th><th>Ruimtes / functies</th><th>Verdeling</th><th>Geometrische zone-unie</th><th>Onderzoeksintenties / controle</th></tr></thead><tbody>${project.variants.map(x=>{const m=metrics(x),sc=x.scale,groups=Object.keys(colors).map(g=>g+': '+m.rooms.filter(o=>o.user===g).length).join(' · '),names=m.rooms.map(o=>o.name+': '+(D.rooms[o.function]?.name||'geen functie')).join('; '),a=coverage(x);return `<tr><th>${esc(x.name)}</th><td>${m.rooms.length} · ${esc(names||'geen')}</td><td>${groups}</td><td>${sc?num(m.union*sc*sc)+' m²':'schaal ontbreekt'}<br>Broncontour ${sc&&m.gross!==null?num(m.gross*sc*sc)+' m²':'onbekend'}</td><td>${a.length} unieke uitspraken gemarkeerd; geen vervullingsscore. ${m.overlap>.01?'Overlap. ':''}${m.outside>.01?'Buiten contour. ':''}Bouwkundige toets nodig.</td></tr>`}).join('')}</tbody></table></div></section>`;}
function ask(message,value=''){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='studio-dialog';dialog.innerHTML='<h3>Ontwerpstudio</h3><p></p><label>Waarde<input type="text" aria-label="Waarde"></label><div class="dialog-actions"><button type="button" data-answer="cancel" class="btn">Annuleren</button><button type="button" data-answer="ok" class="btn primary">Bevestigen</button></div>';dialog.querySelector('p').textContent=message;const input=dialog.querySelector('input');input.value=value??'';function finish(ok){const result=ok?input.value:null;dialog.close();dialog.remove();resolve(result);}dialog.addEventListener('click',e=>{const a=e.target.closest('[data-answer]');if(a){e.stopPropagation();finish(a.dataset.answer==='ok');}});dialog.addEventListener('cancel',e=>{e.preventDefault();finish(false);});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();e.stopPropagation();finish(true);}});root.append(dialog);dialog.showModal();input.focus();input.select();});}
function askConfirm(message){return ask(message,'JA').then(x=>x!==null&&x.trim().toUpperCase()==='JA');}
function download(blob,name){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);}
async function openJSON(e){const file=e.target.files[0];if(!file)return;try{const p=JSON.parse(await file.text());validate(p);if(!await askConfirm('Deze JSON openen vervangt de huidige lokale verzameling. Eerst bewaren? Kies Annuleren om eerst te exporteren.'))return;project=p;selected=[];undo=[];redo=[];save('Ontwerpen teruggehaald inclusief schaal, objecten en onderzoeksrelaties.');refresh();}catch(err){notice='JSON niet geopend: '+err.message;status();}finally{e.target.value='';}}
function validate(p){if(p.version!==3||!Array.isArray(p.variants)||!p.variants.length||p.variants.length>100)throw Error('ongeldig projectformaat');const ids=new Set();for(const x of p.variants){if(typeof x.id!=='string'||ids.has(x.id)||typeof x.name!=='string')throw Error('ongeldige variant-ID');ids.add(x.id);if(!x.base||!/^data:image\/(svg\+xml|png|jpeg)/.test(x.base.uri)||x.base.uri.length>10000000)throw Error('ongeldige onderlegger');if(!Array.isArray(x.base.viewBox)||x.base.viewBox.length!==4||!x.base.viewBox.every(Number.isFinite)||x.base.viewBox[2]<=0||x.base.viewBox[3]<=0)throw Error('ongeldig coördinatenstelsel');if(x.scale!==null&&(!Number.isFinite(x.scale)||x.scale<=0))throw Error('ongeldige schaal');if(!Array.isArray(x.camera)||x.camera.length!==4||!x.camera.every(Number.isFinite))throw Error('ongeldig zichtvenster');if(!Array.isArray(x.objects)||x.objects.length>10000)throw Error('te veel of ongeldige objecten');const objids=new Set();for(const o of x.objects){if(typeof o.id!=='string'||objids.has(o.id)||!['room','wall','door','measure','furniture'].includes(o.type)||![o.x,o.y].every(Number.isFinite))throw Error('ongeldig object');objids.add(o.id);if(['wall','measure'].includes(o.type)){if(![o.x2,o.y2].every(Number.isFinite))throw Error('ongeldige lijn');}else if(!Number.isFinite(o.w)||o.w<=0)throw Error('ongeldige breedte');if(o.type==='room'||o.type==='furniture'){if(!Number.isFinite(o.h)||o.h<=0)throw Error('ongeldige diepte');}if(o.parts&&!o.parts.every(r=>[r.x,r.y,r.w,r.h].every(Number.isFinite)&&r.w>0&&r.h>0))throw Error('ongeldige samengestelde ruimte');if(o.function&&!D.rooms[o.function])throw Error('onbekende onderzoeksfunctie');if(o.wishes&&!o.wishes.every(id=>typeof id==='string'))throw Error('onbekende onderzoeksrelatie');}}if(!ids.has(p.active))throw Error('actieve variant ontbreekt');}
function sanitizeSVG(text){const doc=new DOMParser().parseFromString(text,'image/svg+xml');if(doc.querySelector('parsererror'))throw Error('SVG niet leesbaar');const s=doc.documentElement;if(s.localName!=='svg')throw Error('geen SVG');s.querySelectorAll('script,foreignObject,iframe,object,embed,animate,set').forEach(n=>n.remove());for(const n of [s,...s.querySelectorAll('*')])for(const a of [...n.attributes]){if(/^on/i.test(a.name)||/javascript:|https?:|url\(/i.test(a.value)||(a.name==='href'||a.name==='xlink:href')&&!a.value.startsWith('data:image/'))n.removeAttribute(a.name);}for(const css of s.querySelectorAll('style'))css.textContent=css.textContent.replace(/@import[^;]*;/gi,'').replace(/url\([^)]*\)/gi,'none').replace(/expression\([^)]*\)/gi,'none');let vb=(s.getAttribute('viewBox')||'').trim().split(/[ ,]+/).map(Number);if(vb.length!==4||!vb.every(Number.isFinite)){const w=parseFloat(s.getAttribute('width')),h=parseFloat(s.getAttribute('height'));if(!(w>0&&h>0))throw Error('SVG mist viewBox of afmetingen');vb=[0,0,w,h];}s.setAttribute('xmlns',NS);return{uri:svgData(new XMLSerializer().serializeToString(s)),viewBox:vb};}
async function importBase(e){const file=e.target.files[0];if(!file)return;try{let b;if(/\.svg$|\.html?$/i.test(file.name)){let text=await file.text();if(/\.html?$/i.test(file.name)){const doc=new DOMParser().parseFromString(text,'text/html'),s=doc.querySelector('svg');if(!s)throw Error('geen SVG-plattegrond in HTML gevonden');const css=doc.querySelectorAll('style');for(const c of css){const n=doc.createElementNS(NS,'style');n.textContent=c.textContent;s.prepend(n);}text=s.outerHTML;}b=sanitizeSVG(text);}else{if(!['image/png','image/jpeg'].includes(file.type))throw Error('gebruik PNG, JPG, SVG of HTML met SVG; zet een PDF-pagina eerst om naar een afbeelding');const uri=await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(file);}),img=await loadImage(uri);b={uri,viewBox:[0,0,54,54*img.naturalHeight/img.naturalWidth]};}const nv=fresh('Onderlegger – '+file.name);nv.base={...b,name:file.name,builtin:false,contour:null,note:'Door gebruiker geïmporteerd; schaal en bestaande constructie niet geverifieerd.'};nv.camera=copy(b.viewBox);project.variants.push(nv);project.active=nv.id;selected=[];undo=[];redo=[];tool='calibrate';save('Onderlegger geïmporteerd in nieuwe variant. Kalibreer twee punten met een bekende maat.');refresh();}catch(err){notice='Import mislukt: '+err.message;status();}finally{e.target.value='';}}
function loadImage(uri){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('afbeelding niet leesbaar'));im.src=uri;});}
async function exportDesign(type){const vv=v(),b=vv.base,[x,y,w,h]=b.viewBox;const markup=`<svg xmlns="${NS}" width="1800" height="${Math.round(1800*h/w)}" viewBox="${[x,y,w,h].join(' ')}">${contents(true)}</svg>`,img=await loadImage(svgData(markup)),canvas=document.createElement('canvas');canvas.width=2000;canvas.height=Math.ceil(2000*h/w)+210;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#214b39';ctx.font='bold 30px Arial';ctx.fillText('De Manege – '+vv.name,36,44);ctx.font='19px Arial';ctx.fillText('Ontwerpvoorstel · '+new Date().toLocaleDateString('nl-NL')+' · '+(vv.scale?vv.scaleNote:'schaal niet bevestigd'),36,78);ctx.drawImage(img,20,100,1960,1960*h/w);const foot=120+1960*h/w;ctx.font='17px Arial';let lx=35;for(const [n,c]of Object.entries(colors)){ctx.fillStyle=c;ctx.fillRect(lx,foot,18,18);ctx.fillStyle='#244d3a';ctx.fillText(n,lx+25,foot+15);lx+=n.length*10+65;}ctx.fillText('Originele onderlegger vergrendeld. Nieuwe elementen conceptueel; bouwkundige toets vereist.',35,foot+50);if(type==='png'){canvas.toBlob(blob=>download(blob,'Manege-'+vv.name+'.png'),'image/png');notice='PNG geëxporteerd met titel, datum, legenda en schaalstatus.';status();}else{const jpg=canvas.toDataURL('image/jpeg',.92),bytes=Uint8Array.from(atob(jpg.split(',')[1]),c=>c.charCodeAt(0)),pw=1190.55,ph=841.89,iw=1100,ih=iw*canvas.height/canvas.width,drawH=Math.min(ih,760),drawW=drawH*canvas.width/canvas.height,px=(pw-drawW)/2,py=35,scale=vv.scale?(w*vv.scale*1000)/((drawW*1960/2000)*25.4/72):null,label=scale?'Schaal circa 1:'+Math.round(scale)+' bij A3, 100% afdruk.':'Geen metrische schaal bevestigd.';download(pdfImage(bytes,canvas.width,canvas.height,pw,ph,px,py,drawW,drawH,label),'Manege-'+vv.name+'.pdf');notice='PDF (A3 liggend) geëxporteerd. Afdrukken op 100% voor de vermelde schaal.';status();}}
function pdfImage(jpeg,w,h,pw,ph,x,y,dw,dh,label){const enc=new TextEncoder(),chunks=[],offset=[0];let size=0;const add=s=>{const b=typeof s==='string'?enc.encode(s):s;chunks.push(b);size+=b.length;};add('%PDF-1.4\n');function object(n,body){offset[n]=size;add(n+' 0 obj\n');add(body);add('\nendobj\n');}object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');object(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 4 0 R >> /Font << /F1 6 0 R >> >> /Contents 5 0 R >>`);offset[4]=size;add(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${w} /Height ${h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);add(jpeg);add('\nendstream\nendobj\n');const stream=`q ${dw} 0 0 ${dh} ${x} ${y} cm /Im0 Do Q\nBT /F1 10 Tf 35 18 Td (${label.replace(/[()\\]/g,'')}) Tj ET`;object(5,`<< /Length ${enc.encode(stream).length} >>\nstream\n${stream}\nendstream`);object(6,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');const start=size;add('xref\n0 7\n0000000000 65535 f \n');for(let i=1;i<=6;i++)add(String(offset[i]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<< /Size 7 /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'});}
document.addEventListener('keydown',e=>{if(!document.getElementById('studio-root')||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();action(e.shiftKey?'redo':'undo');return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();action('redo');return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();action('save');return;}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();action('delete');return;}if(e.key==='Escape'){tool='select';draft=null;gesture=null;calPoints=[];draw();return;}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selected.length){e.preventDefault();checkpoint();const step=cell()*(e.shiftKey?10:1),dx=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,dy=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;selected.map(obj).filter(Boolean).forEach(o=>{o.x+=dx;o.y+=dy;if('x2'in o){o.x2+=dx;o.y2+=dy;}});commit();}});
window.ManegeStudio={template,mount,geometry:{unionArea,clipRect,fitCamera},validate,
 focusDrawing:()=>{fitView();root.querySelector('.three').classList.remove('hide-inspector');fitView();root.querySelector('.stage').scrollIntoView({block:'start',behavior:'instant'});},
 getVariant:()=>copy(v()),getProject:()=>copy(project),
 selectVariant:variantId=>{if(!project.variants.some(x=>x.id===variantId))return false;project.active=variantId;selected=[];undo=[];redo=[];save();refresh();return true;},
 setGeneratorConfig:c=>{v().generatorConfig=copy(c);if(v().generation)v().generation.config=copy(c);save('Eigen generatorcriteria opgeslagen.');},
 appendGeneratedVariants:variants=>{for(const vv of variants)validate({version:3,active:vv.id,variants:[vv]});project.variants.push(...variants.map(copy));project.active=variants[0].id;selected=[];undo=[];redo=[];save('Nieuwe generatievarianten opgeslagen; bronvariant behouden.');refresh();},
 selectObject:objectId=>{if(!obj(objectId))return;selected=[objectId];tool='select';draw();inspector();root.querySelector('#st-inspector').scrollIntoView({block:'nearest'});}
};
